const raw = ($input.first().json.message?.text || '').replace(/^کف\s*قیمت\s*/, '').trim();
let query = raw || 'دیسک و صفحه پراید';
let city = 'tehran';
const cityMap = {'تهران':'tehran','مشهد':'mashhad','اصفهان':'isfahan','شیراز':'shiraz','تبریز':'tabriz','کرج':'karaj','اهواز':'ahvaz','قم':'qom','یزد':'yazd','رشت':'rasht'};
if (raw.includes(' در ')) {
  const parts = raw.split(' در ');
  query = parts[0].trim();
  const cFa = parts[1].trim();
  city = cityMap[cFa] || 'tehran';
}
return [{ json: { query, city, encodedQuery: encodeURIComponent(query) } }];

const md = $input.first().json.data || '';
const re = /## \[(.*?)\]\((https:\/\/divar\.ir\/v\/[^\)]+)\)/g;
const pDigits = {'۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9'};
const ads = [];
let m;
while ((m = re.exec(md)) !== null) {
  const clean = m[1].replace(/!\[Image[^\]]*\]\([^\)]+\)/g, '').replace(/\s+/g, ' ').trim();
  const pm = clean.match(/([\d۰-۹,٬]+)\s*تومان/);
  if (!pm) continue;
  const numStr = pm[1].replace(/[۰-۹]/g, d => pDigits[d]).replace(/[^\d]/g, '');
  const price = parseInt(numStr || '0', 10);
  if (price < 50000) continue;
  const title = clean.slice(0, pm.index).trim();
  if (/تعمیر|لنت کوبی|مکانیکی|اجرت/.test(title)) continue;
  ads.push({ title, price, url: m[2] });
}
ads.sort((a, b) => a.price - b.price);
const floor = ads[0]?.price || 0;
const trapPrice = Math.max(50000, Math.round((floor * 0.95) / 10000) * 10000);
return [{ json: { count: ads.length, floor_price: floor, amin_trap_price: trapPrice, cheapest: ads.slice(0, 6) } }];
